/// <summary>
/// The <c>AVASysOperationServiceControllerCls_Extension</c> represents a extension of SysOperationServiceController class.
/// </summary>
/// <remarks>
/// AVA_7303_9393_ContainerLabelOnClose
/// </remarks>
[
    ExtensionOf(classStr(SysOperationServiceController))
]
final class AVASysOperationServiceControllerCls_Extension
{
}

Method.Source:
/// <summary>
/// Executes the service operation associated with the controller.
/// </summary>
/// <returns>
/// An enumeration value that describes how the service operation was executed or if it was canceled is
/// returned.
/// </returns>
/// <remarks>
/// Call this method to execute service operations from code. Do not use the <c>run</c> method.
/// <c>parmShowDialog</c> can be used to suppress the UI if it is needed.
/// </remarks>
public SysOperationStartResult startOperation()
{
    SysOperationStartResult             sysOperationStartResult;

    AVAContainerLabelPrintIDisposable   avaContainerLabelPrintIDisposable;

    avaContainerLabelPrintIDisposable = AVAContainerLabelPrintIDisposable::current();

    if (avaContainerLabelPrintIDisposable)
    {
        this.parmShowDialog(avaContainerLabelPrintIDisposable.showDialog);
        this.parmLoadFromSysLastValue(false);
    }

    sysOperationStartResult = next startOperation();

    return sysOperationStartResult;

}
